  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 13, $j$4.1 Realism and the Ordinary Life$j$, $j${"readings": [{"title": "Proverbs 26 (King James Version)", "url": "/portal/bible/Proverbs/26"}], "body": "After the Civil War, many American writers wanted to show life as it really was. This movement is called Realism. Writers such as Mark Twain, William Dean Howells and Henry James wrote about ordinary people, believable events and the language people actually spoke. They avoided exaggerated adventures and gave careful attention to details.\n\nKey features of Realism:\n1. Ordinary characters and everyday settings.\n2. Believable events and motives.\n3. Natural dialogue, sometimes in regional speech.\n4. Attention to social conditions such as work, class and family.\n\nDialect is a way of speaking that belongs to a region or group. Authors use dialect to make characters sound real. Readers should treat dialect with respect and not as a joke.\n\nTo restate a passage, put its main points into your own words without changing the meaning.\n\nRead this original realistic passage:\n\nHattie took the bread out of the oven and set it on the sill. Outside, the neighbor's boy was shouting about a lost goat. Her mother, tired from the wash, only said, Let him look. He will find it by supper, or he will find out where it went.\n\nRestatement: Hattie finished baking bread while a neighbor boy searched noisily for a missing goat. Her tired mother said he would either find the goat or learn where it had gone, so there was no need to worry.\n\nRealistic features: ordinary tasks (baking, washing), believable dialogue, a calm family tone.\n\nYour task: (1) List two realistic features in the passage. (2) Restate the passage in your own words. (3) Explain what the dialogue shows about the mother.\n\nFlorida standards: ELA.11.R.1.1, ELA.11.R.3.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.R.1.1, ELA.11.R.3.2", "script": "Welcome to a new chapter in American literature. After the Civil War, many writers wanted to show life as it really was. We call this movement Realism. Mark Twain, William Dean Howells and Henry James wrote about ordinary people, believable events and the way people actually talked.\n\nListen to the key features. Ordinary characters and everyday settings. Believable events and motives. Natural dialogue, sometimes in regional speech. And careful attention to social conditions like work, class and family.\n\nNow watch this. Dialect is a way of speaking that belongs to a region or a group. Authors use dialect to make characters sound real. And as readers, we treat dialect with respect. It is never a joke.\n\nAnother skill is restating. To restate a passage, put its main points into your own words without changing the meaning.\n\nLet us read an original realistic passage. Hattie took the bread out of the oven and set it on the sill. Outside, the neighbor's boy was shouting about a lost goat. Her mother, tired from the wash, only said, Let him look. He will find it by supper, or he will find out where it went.\n\nHere is a restatement. Hattie finished baking bread while a neighbor boy searched noisily for a missing goat. Her tired mother said he would either find the goat or learn where it had gone, so there was no need to worry.\n\nThe realistic features are the ordinary tasks, baking and washing, the believable dialogue, and the calm family tone.\n\nYour task today. List two realistic features. Restate the passage in your own words. And explain what the dialogue shows about the mother. Take the four question check when you finish.\n\nThe faithful in small things are faithful in great. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.1 Realism and the Ordinary Life$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 14, $j$4.2 Regionalism, Setting and Voice$j$, $j${"readings": [{"title": "Ruth 2 (King James Version)", "url": "/portal/bible/Ruth/2"}], "body": "Regionalism, also called local color writing, focuses on one region of the country: its landscape, customs, speech and people. Sarah Orne Jewett wrote about Maine. Kate Chopin wrote about Louisiana. Bret Harte wrote about California mining camps. Mark Twain wrote about life along the Mississippi River.\n\nSetting is more than a place. It includes:\n1. Time (era, season, time of day).\n2. Place (region, building, landscape).\n3. Social setting (customs, class, beliefs).\n\nA strong setting affects the characters and events. Weather, work and local customs can shape what people choose to do.\n\nVoice is the personality that comes through the words of an author or a narrator. Word choice, sentence length and tone create voice.\n\nRead this original passage:\n\nIn the bayou country, the afternoon heat sat on the roofs like a weight. Old Etienne mended his net on the porch and hummed a song his mother had taught him. The water was low this year, and everyone in the village spoke of it in quiet voices, as people speak of a sick friend.\n\nSetting: a bayou village in the heat of afternoon. Social setting: a community of fishers who watch the water together. Voice: quiet, observant, respectful. Contribution of setting: the low water raises worry and shows how the people depend on the land.\n\nYour task: (1) Name the time, place and social setting. (2) Describe the narrator's voice in three words. (3) Explain how the setting shapes what the characters feel.\n\nFlorida standards: ELA.11.R.1.1, ELA.11.R.1.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.R.1.1, ELA.11.R.1.3", "script": "Now we travel across the country through the pages of Regionalism. Regionalism, also called local color writing, focuses on one region, its landscape, its customs, its speech and its people.\n\nSarah Orne Jewett wrote about Maine. Kate Chopin wrote about Louisiana. Bret Harte wrote about California mining camps. And Mark Twain wrote about life along the Mississippi River.\n\nListen, a setting is more than a place. It has three parts. Time, which includes the era, the season and the time of day. Place, which includes the region, the building and the landscape. And social setting, which includes customs, class and beliefs. A strong setting affects what the characters feel and do. Weather, work and local customs can shape choices.\n\nNow watch this. Voice is the personality that comes through the words of an author or a narrator. Word choice, sentence length and tone create voice.\n\nLet us read an original passage. In the bayou country, the afternoon heat sat on the roofs like a weight. Old Etienne mended his net on the porch and hummed a song his mother had taught him. The water was low this year, and everyone in the village spoke of it in quiet voices, as people speak of a sick friend.\n\nThe time is a hot afternoon. The place is a bayou village. The social setting is a community of fishers who watch the water together. The voice is quiet, observant and respectful. And the setting contributes by showing worry about the low water and how much the people depend on the land.\n\nYour task today. Name the time, place and social setting. Describe the narrator's voice in three words. And explain how the setting shapes what the characters feel. Take the four question check when you finish.\n\nKnow your place, and love the people in it. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.2 Regionalism, Setting and Voice$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 15, $j$4.3 Naturalism, Stephen Crane and Man Against Nature$j$, $j${"readings": [{"title": "Job 38 (King James Version)", "url": "/portal/bible/Job/38"}], "body": "Naturalism is a movement that grew out of Realism. Naturalist writers, such as Stephen Crane, Jack London and Theodore Dreiser, showed characters struggling against forces they could not control: nature, poverty, heredity or society. Their tone is often cold and detached, and their stories often show how small a person can seem against a powerful world.\n\nKey features of Naturalism:\n1. Characters face powerful outside forces.\n2. The narrator may seem objective and unemotional.\n3. Setting is almost a character, for example, a storm, a freezing wilderness or a crowded city.\n4. Themes of survival, fate and the limits of human control.\n\nA Christian reader notices where these stories differ from Scripture. The Bible teaches that God is in control. Psalm 46:1 says, God is our refuge and strength, a very present help in trouble. A reader can study naturalist stories to understand human struggle while holding on to hope in God.\n\nContrast again shapes point of view. In a naturalist story, the author may contrast a small human with a large, indifferent setting.\n\nRead this original passage:\n\nThe sea rose gray and wide, and the little boat rocked like a seed in a bowl. The men bent to their oars. The waves did not care. They rose and fell as they always had, with no thought of the men, the boat or the shore that waited.\n\nFeatures: powerful setting (the sea), small characters (the men), objective narrator. Contrast: little boat against wide sea. Theme: human limits.\n\nYour task: (1) Identify two naturalist features. (2) Explain the contrast between the men and the sea. (3) Write a short response comparing this view with Psalm 46:1.\n\nFlorida standards: ELA.11.R.1.3, ELA.11.R.3.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.R.1.3, ELA.11.R.3.1", "script": "Now we study a movement that grew out of Realism, called Naturalism. Naturalist writers like Stephen Crane, Jack London and Theodore Dreiser showed characters struggling against forces they could not control. Nature, poverty, heredity or society. The tone of these stories is often cold and detached, and they often show how small a person can seem against a powerful world.\n\nListen to the key features. Characters face powerful outside forces. The narrator may seem objective and unemotional. The setting is almost a character, like a storm, a freezing wilderness or a crowded city. And the themes are survival, fate and the limits of human control.\n\nNow watch this. As Christian readers, we notice where these stories differ from Scripture. The Bible teaches that God is in control. Psalm forty six, verse one says, God is our refuge and strength, a very present help in trouble. We can study naturalist stories to understand human struggle, while holding on to hope in God.\n\nContrast shapes point of view here too. In a naturalist story, an author may set a small human next to a large and indifferent setting.\n\nLet us read an original passage. The sea rose gray and wide, and the little boat rocked like a seed in a bowl. The men bent to their oars. The waves did not care. They rose and fell as they always had, with no thought of the men, the boat or the shore that waited.\n\nThe features are a powerful setting, the sea, small characters, the men, and an objective narrator. The contrast is the little boat against the wide sea. And the theme is human limits.\n\nYour task today. Identify two naturalist features. Explain the contrast between the men and the sea. And write a short response comparing this view with Psalm forty six, verse one. Take the four question check when you finish.\n\nEven when the sea is wide, our God is wider. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.3 Naturalism, Stephen Crane and Man Against Nature$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 16, $j$4.4 Reading Closely: Vocabulary in Context and Implied Meaning$j$, $j${"readings": [{"title": "Luke 8 (King James Version)", "url": "/portal/bible/Luke/8"}], "body": "Good readers pay attention to word meanings. Words can have a literal meaning (the dictionary meaning) and an implied meaning (what the word suggests beyond its definition). The connotation of a word is the feeling or idea attached to it. Compare the words thin and skinny, or determined and stubborn. They are similar, but they carry different feelings.\n\nTo find the meaning of a hard word, use context clues:\n1. Definition clue: the sentence gives the meaning.\n2. Synonym or antonym clue: a similar or opposite word is nearby.\n3. Example clue: examples show what the word means.\n4. Inference: use the whole passage to figure it out.\n\nRead this original passage:\n\nThe mayor's speech was long and ornate, full of fancy words that sparkled but said little. The farmers, who were practical people, listened politely and then went back to their work. They preferred plain sentences with a harvest in them.\n\nThe word ornate means decorated with elaborate detail. Context clue: fancy words that sparkled but said little. The implied meaning of the whole passage: the farmers valued plain speech over empty decoration.\n\nAllegory and implied meaning work together. A reader asks, What does the author suggest beyond the plain words? In Proverbs 15:23, the Bible says, A man hath joy by the answer of his mouth: and a word spoken in due season, how good is it!\n\nYour task: (1) Use context clues to define the word ornate. (2) Explain the difference in connotation between the words plain and dull. (3) State the implied message of the passage.\n\nFlorida standards: ELA.11.V.1.3, ELA.11.R.3.1, ELA.11.R.1.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.V.1.3, ELA.11.R.3.1, ELA.11.R.1.3", "script": "Today we sharpen a skill every good reader needs, the skill of close reading. We begin with words. Words can have a literal meaning, the dictionary meaning, and an implied meaning, what the word suggests beyond its definition. The feeling or idea attached to a word is its connotation. Compare thin and skinny. Compare determined and stubborn. They are close, but they carry different feelings.\n\nNow watch this. To find the meaning of a hard word, we use context clues. A definition clue means the sentence gives the meaning. A synonym or antonym clue means a similar or opposite word is nearby. An example clue means examples show what the word means. And inference means we use the whole passage to figure it out.\n\nLet us read an original passage. The mayor's speech was long and ornate, full of fancy words that sparkled but said little. The farmers, who were practical people, listened politely and then went back to their work. They preferred plain sentences with a harvest in them.\n\nThe word ornate means decorated with elaborate detail. Our context clue is fancy words that sparkled but said little. And the implied meaning of the whole passage is that the farmers valued plain speech over empty decoration.\n\nAllegory and implied meaning work together. A good reader asks, what does the author suggest beyond the plain words? And listen to Proverbs chapter fifteen, verse twenty three. A man hath joy by the answer of his mouth: and a word spoken in due season, how good is it!\n\nYour task today. Use context clues to define the word ornate. Explain the difference in connotation between plain and dull. And state the implied message of the passage. Take the four question check when you finish.\n\nChoose your words as carefully as a craftsman chooses his tools. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.4 Reading Closely: Vocabulary in Context and Implied Meaning$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Assessment 4: Setting and Theme Analysis$j$, $j${"prompt": "Read this original passage and write an analysis of at least 150 words.\n\nIn the mining town of Silver Creek, winter came early and stayed late. Ben Hollis worked the long shift underground and walked home in the dark. His wife kept a lamp in the window every night, whether he was late or not. When the mine caved in near Christmas, the whole town came out with lanterns, and by morning every man was found. Nobody said much. The lamps simply stayed lit.\n\nIn your analysis: (1) Name the time, place and social setting. (2) Identify two features of Realism, Regionalism or Naturalism in the passage. (3) Explain how the setting shapes the characters and events. (4) State one theme and support it with a quotation. (5) Connect the theme to Galatians 6:2, which says, Bear ye one another's burdens, and so fulfil the law of Christ. (6) Use complete sentences with a clear opening and conclusion.", "rubric": "100 points. Setting identified: 15 points. Movement features with evidence: 20 points. Setting's effect on characters and events: 20 points. Theme with quotation: 20 points. Scripture connection: 15 points. Grammar and organization: 10 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 4: Setting and Theme Analysis$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 4, $j$Discussion 4: Ordinary People, Extraordinary Faithfulness$j$, $j${"prompt": "Realism, Regionalism and Naturalism show us ordinary people facing real hardships. Write a post of at least 120 words that (1) explains why stories about ordinary people can be powerful, (2) describes a time when you saw ordinary kindness make a difference, (3) tells how faith can help a person face forces they cannot control, and (4) connects your answer to Psalm 46:1, which says, God is our refuge and strength, a very present help in trouble. Then write a respectful reply of at least 40 words to another student, or answer this question: What does a writer gain by describing everyday life honestly? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 4: Ordinary People, Extraordinary Faithfulness$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Check 4.1: Realism and the Ordinary Life$j$, $j${"questions": [{"q": "Realism tries to:", "options": ["Avoid ordinary people", "Show life as it really is", "Use only magic", "Describe only fantasy"]}, {"q": "Dialect is:", "options": ["A kind of punctuation", "A way of speaking tied to a region or group", "A kind of rhyme", "A type of poem"]}, {"q": "To restate a passage is to:", "options": ["Copy it exactly", "Put it in your own words without changing meaning", "Add new facts", "Change the topic"]}, {"q": "Which writer is associated with Realism?", "options": ["Edgar Allan Poe", "Patrick Henry", "Anne Bradstreet", "Mark Twain"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Realism and the Ordinary Life$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,1,3}'::int[], array[$j$Realism focuses on believable life.$j$,$j$Dialect belongs to a place or group.$j$,$j$Restating keeps the meaning in new words.$j$,$j$Twain wrote in the realist tradition.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Realism and the Ordinary Life$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 17, $j$Check 4.2: Regionalism, Setting and Voice$j$, $j${"questions": [{"q": "Regionalism focuses on:", "options": ["Only kings", "Only outer space", "A particular region's landscape, customs and speech", "Only city life"]}, {"q": "Social setting includes:", "options": ["Customs, class and beliefs", "Only the weather", "Only the title", "Only the date"]}, {"q": "Voice is:", "options": ["The personality that comes through the words", "A kind of rhyme", "A type of paragraph", "A loud sound"]}, {"q": "Kate Chopin wrote about:", "options": ["Alaska", "Hawaii", "Louisiana", "Maine"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Regionalism, Setting and Voice$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,0,2}'::int[], array[$j$Regionalism highlights a specific area.$j$,$j$Social setting is about community and customs.$j$,$j$Voice is the personal style of the text.$j$,$j$Chopin wrote about Louisiana life.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Regionalism, Setting and Voice$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 18, $j$Check 4.3: Naturalism, Stephen Crane and Man Against Nature$j$, $j${"questions": [{"q": "Naturalism often shows characters:", "options": ["Struggling against forces they cannot control", "Living only in fairy tales", "Ignoring all problems", "Winning every contest easily"]}, {"q": "The tone of naturalist writing is often:", "options": ["Silly", "Cold and detached", "Always angry", "Always joyful"]}, {"q": "Psalm 46:1 says God is:", "options": ["Far away", "Our refuge and strength", "Unknown", "A stranger"]}, {"q": "A setting that acts almost like a character is common in:", "options": ["Grammar books", "Naturalism", "Nursery rhymes only", "Math"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Naturalism, Stephen Crane and Man Against Nature$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,1,1}'::int[], array[$j$Naturalism highlights powerful outside forces.$j$,$j$Naturalist narrators often seem objective.$j$,$j$Psalm 46:1 says God is our refuge and strength, a very present help in trouble.$j$,$j$In Naturalism, setting can be a powerful force.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Naturalism, Stephen Crane and Man Against Nature$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 19, $j$Check 4.4: Reading Closely: Vocabulary in Context and Implied Meaning$j$, $j${"questions": [{"q": "Connotation is:", "options": ["The rhyme of a word", "The spelling of a word", "The feeling or idea attached to a word", "The number of letters"]}, {"q": "A context clue is:", "options": ["A hint in nearby words that shows meaning", "The author's name", "A footnote", "A page number"]}, {"q": "An implied meaning is:", "options": ["The first word", "A date", "A dictionary entry", "What a text suggests beyond the plain words"]}, {"q": "In the passage, ornate most nearly means:", "options": ["Quiet", "Decorated with elaborate detail", "Late", "Short"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Reading Closely: Vocabulary in Context and Implied Meaning$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,3,1}'::int[], array[$j$Connotation is the suggested feeling of a word.$j$,$j$Context clues help define hard words.$j$,$j$Implied meaning is suggested, not stated.$j$,$j$Fancy words that sparkled shows ornate means elaborately decorated.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Reading Closely: Vocabulary in Context and Implied Meaning$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 20, $j$Unit Quiz 4: Realism, Regionalism and Naturalism$j$, $j${"questions": [{"q": "Realism focuses on:", "options": ["Kings only", "Believable people and events", "Magic only", "Space travel"]}, {"q": "Regionalism highlights:", "options": ["A single word", "A specific region and its people", "A single sound", "A single date"]}, {"q": "Naturalism shows characters:", "options": ["Facing forces beyond their control", "Living in a fairy tale", "Controlling everything", "Avoiding all conflict"]}, {"q": "Dialect is:", "options": ["A way of speaking belonging to a region or group", "A kind of rhyme", "A type of title", "A kind of paragraph"]}, {"q": "Connotation is:", "options": ["A rhyme", "The spelling of a word", "The length of a word", "The feeling attached to a word"]}, {"q": "A context clue helps a reader:", "options": ["Find the author's birthday", "Figure out the meaning of a word", "Choose a title", "Count pages"]}, {"q": "Voice is:", "options": ["The volume of a speaker", "The personality that comes through the writing", "The title", "A kind of rhyme"]}, {"q": "Psalm 46:1 says God is our:", "options": ["Enemy", "Refuge and strength", "Stranger", "Silence"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Realism, Regionalism and Naturalism$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,0,0,3,1,1,1}'::int[], array[$j$Realism is about believable life.$j$,$j$Regionalism is local color.$j$,$j$Naturalism stresses outside forces.$j$,$j$Dialect marks regional or group speech.$j$,$j$Connotation is the suggested feeling.$j$,$j$Context clues reveal word meaning.$j$,$j$Voice is the writer's personal style.$j$,$j$Psalm 46:1 says God is our refuge and strength.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Realism, Regionalism and Naturalism$j$ on conflict (item_id) do nothing;
